using System.Collections.Generic;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceSecondActionLogic_RandomTarget_RandomPurifyCorruptAction", menuName = "Data/Battle/Logics/Dice Action/Dice Second Action Logic/DiceSecondActionLogic_RandomTarget_RandomPurifyCorruptAction")]
public class DiceSecondActionLogic_RandomTarget_RandomPurifyCorruptAction : DiceSecondActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void OnDrop(ActionFace actionFace, GameObject target, GameObject source)
	{
		GameObject gameObject = null;
		List<GameObject> list = currentActiveUnits.GetCurrentActiveUnits();
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source))
		{
			GameObject gameObject2 = currentActiveUnits.IsUnitWithElectrostaticField();
			if ((bool)gameObject2)
			{
				ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget = gameObject2;
				gameObject = gameObject2;
			}
			else
			{
				ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget = list.PickRandom();
				gameObject = list.PickRandom();
			}
		}
		else
		{
			ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget = list.PickRandom();
			gameObject = list.PickRandom();
		}
		actionFace.SecondBattleAction.CastTargetAmount(gameObject, actionFace.SecondModifiedActionValue, source);
	}
}
